<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\CompatibilityRule;use Illuminate\Http\Request;
class CompatibilityRuleController extends Controller {public function index(){return response()->json(['data'=>CompatibilityRule::all()]);}public function show(CompatibilityRule $compatibilityRule){return response()->json(['data'=>$compatibilityRule]);}public function store(Request $r){return response()->json(['data'=>CompatibilityRule::create($r->validate(['name'=>'required|string|unique:compatibility_rules,name','description'=>'required|string','is_active'=>'sometimes|boolean']))],201);}public function update(Request $r,CompatibilityRule $compatibilityRule){$compatibilityRule->update($r->validate(['name'=>'required|string|unique:compatibility_rules,name,'.$compatibilityRule->id,'description'=>'required|string','is_active'=>'sometimes|boolean']));return response()->json(['data'=>$compatibilityRule]);}public function destroy(CompatibilityRule $compatibilityRule){$compatibilityRule->delete();return response()->noContent();}}
